using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
// Read-only, same-frame diagnostics. Call on Unity main thread after the target camera has rendered.
public static class DSPRayReceiverAudit {
 [Serializable] public sealed class TextureInfo {public string name,type,format;public int id,width,height,depthBits,samples;public bool created;}
 [Serializable] public sealed class CameraInfo {public string name,projection,gpuProjectionToScreen,gpuProjectionToTexture,view;public int depthMode,mask;public Vector3 position;public Rect pixelRect;public bool enabled,hdr;public TextureInfo target;}
 [Serializable] public sealed class Receiver {public int entityId,protoId,modelId,modelIndex,genId,networkId,catalystId,curCatalystId,catalystCount,catalystPoint,catalystIncLevel,productId;public uint state,expectedState;public Vector3 pos,screen;public float distance,time,power,expectedPower,prepareLength,workingLength,productCount,currentStrength,warmup,ionEnhance;public long capacityCurrentTick,generateCurrentTick,genEnergyPerTick;public bool onScreen,nearby,animPresent;}
 [Serializable] public sealed class Property {public string name;public float scalar;public Vector4 vector;public TextureInfo texture;}
 [Serializable] public sealed class MaterialInfo {public string name,shader,keywords;public int id,queue;public bool supported;public List<Property> properties=new List<Property>();}
 [Serializable] public sealed class Report {public string label,error,limitations;public int frame,planet,width,height,totalGamma,selected,truncated;public long tick;public float realtime,time,timeSinceLevelLoad,timeScale,ionHeight;public Vector4 shaderTime,projectionParams,zBufferParams;public TextureInfo globalDepth;public CameraInfo mainCamera;public List<CameraInfo> cameras=new List<CameraInfo>();public List<Receiver> receivers=new List<Receiver>();public List<MaterialInfo> materials=new List<MaterialInfo>();}
 static TextureInfo Texture(Texture t) {if(!t)return null;var x=new TextureInfo{name=t.name,type=t.GetType().Name,id=t.GetInstanceID(),width=t.width,height=t.height};var rt=t as RenderTexture;if(rt){x.format=rt.graphicsFormat.ToString();x.depthBits=rt.depth;x.samples=rt.antiAliasing;x.created=rt.IsCreated();}else if(t is Texture2D)x.format=((Texture2D)t).format.ToString();return x;}
 static CameraInfo CameraRecord(Camera c) {return new CameraInfo{name=c.name,projection=c.projectionMatrix.ToString("R"),gpuProjectionToScreen=GL.GetGPUProjectionMatrix(c.projectionMatrix,false).ToString("R"),gpuProjectionToTexture=GL.GetGPUProjectionMatrix(c.projectionMatrix,true).ToString("R"),view=c.worldToCameraMatrix.ToString("R"),depthMode=(int)c.depthTextureMode,mask=c.cullingMask,position=c.transform.position,pixelRect=c.pixelRect,enabled=c.enabled,hdr=c.allowHDR,target=Texture(c.targetTexture)};}
 public static void Capture(string output,string label) {
  var r=new Report{label=label,frame=Time.frameCount,tick=GameMain.gameTick,width=Screen.width,height=Screen.height,realtime=Time.realtimeSinceStartup,time=Time.time,timeSinceLevelLoad=Time.timeSinceLevelLoad,timeScale=Time.timeScale,limitations="Shader globals are managed getter queries, not verified GPU constant-buffer values. Observed CPU state; no GPU buffer readback, native attachment proof or shader correctness assertion. Global depth may belong to last-rendered UI camera; correlate capture phase. Local entity coordinates assume ordinary local-planet world view. On-screen means projected bounds only, not occlusion. Metadata reads do not freeze simulation/shader time."};
  try {
   r.shaderTime=Shader.GetGlobalVector("_Time");r.ionHeight=Shader.GetGlobalFloat("_Global_Ion_Height");r.projectionParams=Shader.GetGlobalVector("_ProjectionParams");r.zBufferParams=Shader.GetGlobalVector("_ZBufferParams");r.globalDepth=Texture(Shader.GetGlobalTexture("_CameraDepthTexture"));
   var c=GameCamera.main?GameCamera.main:Camera.main;if(c)r.mainCamera=CameraRecord(c);foreach(var ac in Camera.allCameras)r.cameras.Add(CameraRecord(ac));
   var planet=GameMain.localPlanet;r.planet=planet==null?0:planet.id;var f=planet==null?null:planet.factory;
   if(f!=null && f.powerSystem!=null){var ps=f.powerSystem;for(int i=1;i<ps.genCursor;i++){var g=ps.genPool[i];if(g.id!=i||!g.gamma)continue;r.totalGamma++;if(g.entityId<=0||g.entityId>=f.entityPool.Length)continue;var e=f.entityPool[g.entityId];if(e.id!=g.entityId)continue;var screen=c?c.WorldToScreenPoint(e.pos):Vector3.zero;float d=c?Vector3.Distance(c.transform.position,e.pos):float.MaxValue;bool visible=c&&screen.z>0&&c.pixelRect.Contains(new Vector2(screen.x,screen.y));if(!visible&&d>300f)continue;
    var x=new Receiver{entityId=e.id,protoId=e.protoId,modelId=e.modelId,modelIndex=e.modelIndex,genId=i,networkId=g.networkId,pos=e.pos,screen=screen,distance=d,onScreen=visible,nearby=d<=300f,catalystId=g.catalystId,curCatalystId=g.curCatalystId,catalystCount=g.catalystCount,catalystPoint=g.catalystPoint,catalystIncLevel=g.catalystIncLevel,productId=g.productId,productCount=g.productCount,currentStrength=g.currentStrength,warmup=g.warmup,ionEnhance=g.ionEnhance,capacityCurrentTick=g.capacityCurrentTick,generateCurrentTick=g.generateCurrentTick,genEnergyPerTick=g.genEnergyPerTick,expectedState=(uint)(((g.catalystPoint>0||g.catalystCount>0)?1:0)|((g.productId>0)?2:0)|((g.curCatalystId&0x3fff)<<2)),expectedPower=g.genEnergyPerTick==0?0:(float)((double)g.capacityCurrentTick/g.genEnergyPerTick)};
    if(f.entityAnimPool!=null&&e.id<f.entityAnimPool.Length){var a=f.entityAnimPool[e.id];x.animPresent=true;x.time=a.time;x.power=a.power;x.state=a.state;x.prepareLength=a.prepare_length;x.workingLength=a.working_length;}r.receivers.Add(x);
   }}r.receivers.Sort((a,b)=>a.distance.CompareTo(b.distance));r.selected=r.receivers.Count;if(r.receivers.Count>512){r.truncated=r.receivers.Count-512;r.receivers.RemoveRange(512,r.truncated);}
   foreach(var m in Resources.FindObjectsOfTypeAll<Material>()){if(!m.shader)continue;string sn=m.shader.name;if(sn.IndexOf("Ray Receiver",StringComparison.OrdinalIgnoreCase)<0&&sn.IndexOf("RayReceiver",StringComparison.OrdinalIgnoreCase)<0)continue;var mi=new MaterialInfo{name=m.name,id=m.GetInstanceID(),shader=sn,queue=m.renderQueue,supported=m.shader.isSupported,keywords=string.Join(";",m.shaderKeywords)};
    foreach(var n in new[]{"_EmissionSwitch","_Multiplier","_AlphaMultiplier","_InvFade","_SideFade","_Global_Ion_Height","_Mono_Inst","_Mono_Anim_Time","_Mono_Anim_LP","_Mono_Anim_LW","_Mono_Anim_State","_Mono_Anim_Power","_PortWords_AnimBuffer","_PortWords_InstBuffer","_PortWords_IdBuffer"})if(m.HasProperty(n))mi.properties.Add(new Property{name=n,scalar=m.GetFloat(n)});
    foreach(var n in new[]{"_Beam","_Particle","_Circle","_UVSpeed","_NoiseScale","_GravityLenColor","_DarkFogLenColor","_PolarColor"})if(m.HasProperty(n))mi.properties.Add(new Property{name=n,vector=m.GetVector(n)});
    foreach(var n in new[]{"_MainTex","_MaskTex","_PTex","_AuroraNoise"})if(m.HasProperty(n))mi.properties.Add(new Property{name=n,texture=Texture(m.GetTexture(n))});r.materials.Add(mi);
   }
  }catch(Exception e){r.error=e.ToString();}
  Directory.CreateDirectory(output);foreach(char ch in Path.GetInvalidFileNameChars())label=label.Replace(ch,'_');File.WriteAllText(Path.Combine(output,"ray-receiver-"+label+".json"),JsonUtility.ToJson(r,true));
 }
}
